begin;
set local statement_timeout='25s';
create temp table creation_results(test text,passed boolean) on commit drop;
grant insert,select on creation_results to authenticated,anon;
do $$
declare
 c uuid:=gen_random_uuid(); d uuid:=gen_random_uuid();
 a uuid:=gen_random_uuid(); b uuid:=gen_random_uuid(); pa uuid; pb uuid;
 v uuid; w uuid; f uuid; g uuid; h uuid; s uuid; t uuid; u uuid;
 denied boolean; n bigint; baseline bigint; ct uuid; dt uuid; created uuid;
begin
 if exists(select 1 from cron.job where active) then raise exception 'Disable cron before test'; end if;
 select count(*) into baseline from public.notification_queue;
 insert into public.clubs(id,name) values(c,'ROLLBACK publication own'),(d,'ROLLBACK publication foreign');
 insert into auth.users(id,email,raw_user_meta_data,raw_app_meta_data) values
 (a,a::text||'@example.invalid','{"display_name":"Publication admin"}','{}'),
 (b,b::text||'@example.invalid','{"display_name":"Publication foreign reserve"}','{}');
 select id into pa from public.member_profiles where user_id=a;
 select id into pb from public.member_profiles where user_id=b;
 insert into public.club_memberships(club_id,member_profile_id,role,is_active) values(c,pa,'admin',true),(d,pb,'member',true);
 insert into public.venues(club_id,name,is_home_venue) values(c,'Rollback own venue',false) returning id into v;
 insert into public.venues(club_id,name,is_home_venue) values(d,'Rollback foreign venue',false) returning id into w;
 insert into public.fixtures(club_id,start_at,is_home,venue_id,rinks_required,players_per_rink) values(c,now()+interval '30 days',false,v,1,4) returning id into f;
 insert into public.fixtures(club_id,start_at,is_home,venue_id,rinks_required,players_per_rink) values(c,now()+interval '31 days',false,v,1,4) returning id into h;
 insert into public.fixtures(club_id,start_at,is_home,venue_id,rinks_required,players_per_rink) values(d,now()+interval '32 days',false,w,1,4) returning id into g;
 insert into public.team_selections(fixture_id) values(f) returning id into s;
 insert into public.team_selections(fixture_id) values(g) returning id into t;
 insert into public.team_selections(fixture_id) values(h) returning id into u;
 insert into public.team_selection_members(team_selection_id,member_profile_id,role,is_selected) values(s,pa,'reserve',true),(t,pb,'reserve',true);
 insert into public.competition_types(club_id,name,section,uses_rinks,is_internal) values(c,'Rollback fixture type','mixed',false,true) returning id into ct;
 insert into public.competition_types(club_id,name,section,uses_rinks,is_internal) values(d,'Rollback foreign fixture type','mixed',false,true) returning id into dt;
 reset role; update public.club_memberships set role='member',is_active=true where club_id=c and member_profile_id=pa;
 update public.club_memberships set role='admin' where club_id=d and member_profile_id=pb;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true); set local role authenticated;
 denied:=false; begin perform public.create_fixture_with_setup_v2(c,now()+interval '60 days',now()+interval '60 days 2 hours',true,'mixed',0,1,'singles',ct,'open',p_venue_id=>v); exception when raise_exception then denied:=sqlerrm='You do not have permission to create this fixture.'; end; insert into creation_results values('v2 member denied',denied);
 denied:=false; begin perform public.create_fixture_with_setup(c,now()+interval '61 days',now()+interval '61 days 2 hours',true,'mixed',0,1,'singles',ct,p_venue_id=>v); exception when raise_exception then denied:=sqlerrm='You do not have permission to create this fixture.'; end; insert into creation_results values('legacy member denied',denied);
 reset role; update public.club_memberships set role='guest',is_active=true where club_id=c and member_profile_id=pa;
 update public.club_memberships set role='admin' where club_id=d and member_profile_id=pb;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true); set local role authenticated;
 denied:=false; begin perform public.create_fixture_with_setup_v2(c,now()+interval '60 days',now()+interval '60 days 2 hours',true,'mixed',0,1,'singles',ct,'open',p_venue_id=>v); exception when raise_exception then denied:=sqlerrm='You do not have permission to create this fixture.'; end; insert into creation_results values('v2 guest denied',denied);
 denied:=false; begin perform public.create_fixture_with_setup(c,now()+interval '61 days',now()+interval '61 days 2 hours',true,'mixed',0,1,'singles',ct,p_venue_id=>v); exception when raise_exception then denied:=sqlerrm='You do not have permission to create this fixture.'; end; insert into creation_results values('legacy guest denied',denied);
 reset role; update public.club_memberships set role='admin',is_active=false where club_id=c and member_profile_id=pa;
 update public.club_memberships set role='admin' where club_id=d and member_profile_id=pb;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true); set local role authenticated;
 denied:=false; begin perform public.create_fixture_with_setup_v2(c,now()+interval '60 days',now()+interval '60 days 2 hours',true,'mixed',0,1,'singles',ct,'open',p_venue_id=>v); exception when raise_exception then denied:=sqlerrm='You do not have permission to create this fixture.'; end; insert into creation_results values('v2 inactive admin denied',denied);
 denied:=false; begin perform public.create_fixture_with_setup(c,now()+interval '61 days',now()+interval '61 days 2 hours',true,'mixed',0,1,'singles',ct,p_venue_id=>v); exception when raise_exception then denied:=sqlerrm='You do not have permission to create this fixture.'; end; insert into creation_results values('legacy inactive admin denied',denied);
 reset role; update public.club_memberships set role='admin',is_active=true where club_id=c and member_profile_id=pa;
 update public.club_memberships set role='admin' where club_id=d and member_profile_id=pb;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated')::text,true); set local role authenticated;
 denied:=false; begin perform public.create_fixture_with_setup_v2(c,now()+interval '60 days',now()+interval '60 days 2 hours',true,'mixed',0,1,'singles',ct,'open',p_venue_id=>v); exception when raise_exception then denied:=sqlerrm='You do not have permission to create this fixture.'; end; insert into creation_results values('v2 foreign admin denied',denied);
 denied:=false; begin perform public.create_fixture_with_setup(c,now()+interval '61 days',now()+interval '61 days 2 hours',true,'mixed',0,1,'singles',ct,p_venue_id=>v); exception when raise_exception then denied:=sqlerrm='You do not have permission to create this fixture.'; end; insert into creation_results values('legacy foreign admin denied',denied);
 reset role; update public.club_memberships set role='admin',is_active=true where club_id=c and member_profile_id=pa;
 update public.club_memberships set role='admin' where club_id=d and member_profile_id=pb;
 perform set_config('request.jwt.claims','{}',true); set local role anon;
 denied:=false; begin perform public.create_fixture_with_setup_v2(c,now()+interval '60 days',now()+interval '60 days 2 hours',true,'mixed',0,1,'singles',ct,'open',p_venue_id=>v); exception when insufficient_privilege then denied:=true; end; insert into creation_results values('v2 anonymous denied',denied);
 denied:=false; begin perform public.create_fixture_with_setup(c,now()+interval '61 days',now()+interval '61 days 2 hours',true,'mixed',0,1,'singles',ct,p_venue_id=>v); exception when insufficient_privilege then denied:=true; end; insert into creation_results values('legacy anonymous denied',denied);
 reset role; update public.club_memberships set role='admin',is_active=true where club_id=c and member_profile_id=pa;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true); set local role authenticated;
 denied:=false; begin perform public.create_fixture_with_setup_v2(c,now()+interval '60 days',now()+interval '60 days 2 hours',true,'mixed',0,1,'singles',ct,'open',p_venue_id=>v,p_opponent_venue_id=>w); exception when check_violation then denied:=sqlerrm='Opponent venue does not belong to club'; end; insert into creation_results values('v2 foreign opponent rejected',denied);
 created:=public.create_fixture_with_setup_v2(c,now()+interval '60 days',now()+interval '60 days 2 hours',true,'mixed',0,1,'singles',ct,'open',p_venue_id=>v);
 reset role; insert into creation_results select 'v2 own creation allowed',club_id=c and created_by_user_id=a and opponent_venue_id is null from public.fixtures where id=created; set local role authenticated;
 denied:=false; begin update public.fixtures set opponent_venue_id=w where id=created; exception when check_violation then denied:=sqlerrm='Opponent venue does not belong to club'; end; insert into creation_results values('v2 direct foreign opponent update rejected',denied);
 update public.fixtures set opponent_venue_id=v where id=created;
 reset role; insert into creation_results select 'v2 own opponent update retained',opponent_venue_id=v from public.fixtures where id=created; set local role authenticated;
 denied:=false; begin perform public.create_fixture_with_setup_v2(c,now()+interval '60 days',now()+interval '60 days 2 hours',true,'mixed',0,1,'singles',ct,'open',p_venue_id=>v,p_captain_member_profile_id=>pb); exception when raise_exception then denied:=sqlerrm='The captain/organiser and vice/deputy must be active non-Guest club members.'; end; insert into creation_results values('v2 foreign captain rejected',denied);
 denied:=false; begin perform public.create_fixture_with_setup(c,now()+interval '61 days',now()+interval '61 days 2 hours',true,'mixed',0,1,'singles',ct,p_venue_id=>v,p_opponent_venue_id=>w); exception when check_violation then denied:=sqlerrm='Opponent venue does not belong to club'; end; insert into creation_results values('legacy foreign opponent rejected',denied);
 created:=public.create_fixture_with_setup(c,now()+interval '61 days',now()+interval '61 days 2 hours',true,'mixed',0,1,'singles',ct,p_venue_id=>v);
 reset role; insert into creation_results select 'legacy own creation allowed',club_id=c and created_by_user_id=a and opponent_venue_id is null from public.fixtures where id=created; set local role authenticated;
 denied:=false; begin update public.fixtures set opponent_venue_id=w where id=created; exception when check_violation then denied:=sqlerrm='Opponent venue does not belong to club'; end; insert into creation_results values('legacy direct foreign opponent update rejected',denied);
 update public.fixtures set opponent_venue_id=v where id=created;
 reset role; insert into creation_results select 'legacy own opponent update retained',opponent_venue_id=v from public.fixtures where id=created; set local role authenticated;
 denied:=false; begin perform public.create_fixture_with_setup(c,now()+interval '61 days',now()+interval '61 days 2 hours',true,'mixed',0,1,'singles',ct,p_venue_id=>v,p_captain_member_profile_id=>pb); exception when raise_exception then denied:=sqlerrm='The captain/organiser and vice/deputy must be active non-Guest club members.'; end; insert into creation_results values('legacy foreign captain rejected',denied);
 reset role; insert into public.app_superusers(user_id) values(a); set local role authenticated;
 denied:=false; begin update public.fixtures set opponent_venue_id=w where id=f; exception when check_violation then denied:=sqlerrm='Opponent venue does not belong to club'; end; insert into creation_results values('superuser link integrity enforced',denied);
 reset role;
 insert into creation_results values('cron remains disabled',not exists(select 1 from cron.job where active));
 if exists(select 1 from creation_results where not passed) then raise exception 'Creation checks failed'; end if;
end $$;
select * from creation_results order by test;
rollback;
